package com.ensam.inventia.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; import java.util.*;
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder @Entity @Table(name="submissions")
public class Submission { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false, length=150) private String title; @Column(nullable=false, length=3000) private String description; private String repositoryUrl; private String demoUrl; private String techStack; @Column(nullable=false) private String artifactObjectKey; @Column(nullable=false) private String artifactFileName; @Column(nullable=false) private Long artifactSize; private LocalDateTime submittedAt; private LocalDateTime updatedAt; @OneToOne(optional=false) @JoinColumn(name="team_id", unique=true) private Team team; @OneToMany(mappedBy="submission", cascade=CascadeType.ALL) @Builder.Default private List<Score> scores=new ArrayList<>(); @PrePersist void prePersist(){submittedAt=LocalDateTime.now(); updatedAt=submittedAt;} @PreUpdate void preUpdate(){updatedAt=LocalDateTime.now();} }
